# Model of "du | sort -h": find the biggest folder, then drill into it.
# Time O(N) to total sizes, space O(N) for N paths.
tree = {
    "/var/log/nginx/access.log": 9_200, "/var/log/syslog": 300,
    "/var/lib/docker/overlay/a": 14_500, "/var/lib/docker/overlay/b": 6_100,
    "/home/ann/backup.tar": 2_000, "/etc/hosts": 1,
}

def dir_sizes(files, prefix):
    # Sum sizes (MB) of everything below each direct child of prefix
    totals = {}
    for path, size in files.items():
        if path.startswith(prefix):
            child = path[len(prefix):].split("/")[0]
            totals[child] = totals.get(child, 0) + size
    return totals

prefix = "/"
while True:
    totals = dir_sizes(tree, prefix)
    print("in", prefix, sorted(totals.items(), key=lambda kv: -kv[1]))
    biggest = max(totals, key=totals.get)  # follow only the biggest one
    nxt = prefix + biggest + "/"
    if not any(p.startswith(nxt) for p in tree):
        print("biggest item:", prefix + biggest)
        break
    prefix = nxt
